package com.servicedesk360.controller;
import com.servicedesk360.dto.common.PageResponse; import com.servicedesk360.dto.tenant.*; import com.servicedesk360.service.TeamQueueService; import jakarta.validation.Valid; import org.springframework.data.domain.Pageable; import org.springframework.data.web.PageableDefault; import org.springframework.web.bind.annotation.*;
@RestController @RequestMapping("/api/admin") public class TeamQueueController{private final TeamQueueService service;public TeamQueueController(TeamQueueService s){service=s;}@GetMapping("/teams")public PageResponse<TeamResponse> teams(@PageableDefault(size=50,sort="name")Pageable p){return service.listTeams(p);}@PostMapping("/teams")public TeamResponse team(@Valid @RequestBody TeamRequest r){return service.createTeam(r);}@GetMapping("/queues")public PageResponse<QueueResponse> queues(@PageableDefault(size=50,sort="name")Pageable p){return service.listQueues(p);}@PostMapping("/queues")public QueueResponse queue(@Valid @RequestBody QueueRequest r){return service.createQueue(r);}@GetMapping("/categories")public PageResponse<CategoryResponse> categories(@PageableDefault(size=50,sort="name")Pageable p){return service.listCategories(p);}@PostMapping("/categories")public CategoryResponse category(@Valid @RequestBody CategoryRequest r){return service.createCategory(r);}}
